syntax = "proto3";

service KVStore {
  rpc GetVal(GetValRequest) returns (GetValResponse);
  rpc SetVal(SetValRequest) returns (SetValResponse);
}

message GetValRequest {
  string key = 1;
}

message GetValResponse {
  int32 val = 1;
}

message SetValRequest {
  string key = 1;
  int32 value = 2;
}

message SetValResponse {
  int32 val = 1;
}

"""In-memory gRPC key/value server listening on port 5328."""

from concurrent import futures
import threading

import grpc

import kv_store_pb2
import kv_store_pb2_grpc


class Server(kv_store_pb2_grpc.KVStoreServicer):
    def __init__(self):
        self.store = {}
        self._lock = threading.Lock()

    def GetVal(self, request, context):
        with self._lock:
            if request.key not in self.store:
                context.abort(grpc.StatusCode.NOT_FOUND, "Key not found")
            return kv_store_pb2.GetValResponse(val=self.store[request.key])

    def SetVal(self, request, context):
        with self._lock:
            self.store[request.key] = request.value
            return kv_store_pb2.SetValResponse(val=request.value)


def main():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), server)
    if server.add_insecure_port("[::]:5328") == 0:
        raise RuntimeError("Could not bind port 5328")
    server.start()
    print("KVStore server listening on port 5328", flush=True)
    try:
        server.wait_for_termination()
    except KeyboardInterrupt:
        server.stop(grace=5).wait()


if __name__ == "__main__":
    main()
